import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const cors = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type", "Access-Control-Allow-Methods": "POST, OPTIONS" };
const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });
const truncate = (value: string | null | undefined, limit: number) => (value ?? "").replace(/\s+/g, " ").trim().slice(0, limit);
const safe = (value: string) => value.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 80) || "cover";

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") return new Response("ok", { headers: cors });
  if (request.method !== "POST") return json({ error: "Použij POST požadavek." }, 405);
  const authorization = request.headers.get("Authorization");
  const url = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  if (!authorization || !url || !anonKey) return json({ error: "Chybí bezpečné připojení k externímu cloudu." }, 401);
  const supabase = createClient(url, anonKey, { global: { headers: { Authorization: authorization } } });
  const { data: { user }, error: authError } = await supabase.auth.getUser();
  if (authError || !user) return json({ error: "Neplatné přihlášení." }, 401);
  const input = await request.json().catch(() => null) as { action?: string; entityType?: "song" | "lyric"; entityId?: string; jobId?: string } | null;
  if (!input?.action || !input.entityType || !input.entityId) return json({ error: "Chybí skladba nebo akce." }, 400);
  const table = input.entityType === "song" ? "sc_songs" : "sc_lyrics";
  const { data: entity, error: entityError } = await supabase.from(table).select("id,title,style_prompt,lyrics").eq("id", input.entityId).single();
  if (entityError || !entity) return json({ error: "Položka nebyla nalezena." }, 404);

  if (input.action === "create") {
    const prompt = `Square album cover for the Czech song "${truncate(entity.title, 120)}". Mood and music direction: ${truncate(entity.style_prompt, 600) || "original Czech song"}. Lyrical atmosphere: ${truncate(entity.lyrics, 900)}. Create a cinematic, expressive, premium music artwork, dark charcoal and copper palette, one clear visual subject, rich texture, no lettering, no words, no logos, no watermark, 1:1 composition.`;
    const response = await fetch("https://aihorde.net/api/v2/generate/async", { method: "POST", headers: { "Content-Type": "application/json", apikey: "0000000000", "Client-Agent": "SongCraftStudio:1.0" }, body: JSON.stringify({ prompt, params: { width: 1024, height: 1024, steps: 20, cfg_scale: 6.5, n: 1 }, nsfw: false, censor_nsfw: true, trusted_workers: false, shared: false }) });
    const data = await response.json().catch(() => null) as { id?: string; message?: string } | null;
    if (!response.ok || !data?.id) return json({ error: data?.message || "Cloudová AI nyní nemůže přijmout generování." }, 502);
    return json({ jobId: data.id, message: "Cover se připravuje v cloudové frontě." });
  }

  if (input.action === "check") {
    if (!input.jobId) return json({ error: "Chybí identifikátor generování." }, 400);
    const response = await fetch(`https://aihorde.net/api/v2/generate/status/${input.jobId}`, { headers: { apikey: "0000000000", "Client-Agent": "SongCraftStudio:1.0" } });
    const data = await response.json().catch(() => null) as { done?: boolean; faulted?: boolean; generations?: Array<{ img?: string }> } | null;
    if (!response.ok || !data) return json({ error: "Stav generování se nepodařilo načíst." }, 502);
    if (data.faulted) return json({ status: "failed", error: "Cloudová AI generování nedokončila. Zkus ho spustit znovu." });
    if (!data.done) return json({ status: "processing" });
    const imageUrl = data.generations?.[0]?.img;
    if (!imageUrl) return json({ status: "failed", error: "Cloudová AI nevrátila obrázek." });
    const imageResponse = await fetch(imageUrl);
    const contentType = imageResponse.headers.get("content-type") || "image/webp";
    if (!imageResponse.ok || !contentType.startsWith("image/")) return json({ status: "failed", error: "Výsledný obrázek se nepodařilo načíst." });
    const path = `${user.id}/covers/generated/${input.entityType}-${safe(entity.title)}-${crypto.randomUUID()}.webp`;
    const { error: uploadError } = await supabase.storage.from("songcraft").upload(path, new Uint8Array(await imageResponse.arrayBuffer()), { contentType, upsert: false });
    if (uploadError) return json({ status: "failed", error: uploadError.message });
    const { error: updateError } = await supabase.from(table).update({ cover_path: path }).eq("id", input.entityId);
    if (updateError) return json({ status: "failed", error: updateError.message });
    return json({ status: "completed", coverPath: path });
  }

  return json({ error: "Neznámá akce." }, 400);
});
